from collections import defaultdict

class Broker:
    def __init__(self):
        self.abos = defaultdict(list)

    def subscribe(self, topic, handler):
        self.abos[topic].append(handler)

    def publish(self, topic, msg):
        for handler in self.abos[topic]:
            handler(msg)

b = Broker()
b.subscribe("noten", lambda m: print("App:", m))
b.subscribe("noten", lambda m: print("Mail:", m))
b.publish("noten", "POS: 1")
b.publish("termine", "Matura")  # kein Abo
# App: POS: 1
# Mail: POS: 1

syntax = "proto3";

service Noten {
  rpc Schnitt (NotenListe)
      returns (Ergebnis);
}
message NotenListe {
  repeated int32 noten = 1;
}
message Ergebnis {
  double schnitt = 1;
}
